@CreatedDate       -> ustawiane RAZ, przy pierwszym zapisie (@PrePersist)
@LastModifiedDate  -> aktualizowane PRZY KAZDYM zapisie (@PrePersist + @PreUpdate)
@CreatedBy         -> ustawiane RAZ, WYMAGA AuditorAware
@LastModifiedBy    -> aktualizowane PRZY KAZDYM zapisie, WYMAGA AuditorAware

@Entity
@EntityListeners(AuditingEntityListener.class)
class BlogPost {
    @CreatedDate Instant createdDate;
    @LastModifiedDate Instant lastModifiedDate;
    @CreatedBy String createdBy;
    @LastModifiedBy String lastModifiedBy;
}

@Configuration
@EnableJpaAuditing
class JpaAuditingConfig { }

BlogPost saved = repository.save(new BlogPost("Tytul", "Tresc"));
// createdDate == lastModifiedDate (pierwszy zapis, oba pola rowne)

saved.content = "Zaktualizowana tresc";
repository.save(saved);
// createdDate NIE ZMIENIL SIE, lastModifiedDate JEST PÓZNIEJSZY
